                throw;
            }
            this.Manager.Assert(TestManagerHelpers.Equality(((object)(((int)(this.c.Value.MaxSmbVersionSupported)))), ((object)(770))), "Fail to check the assumption : c.MaxSmbVersionSupported == 770");
            TestManagerHelpers.AssertBind<Microsoft.Protocols.TestSuites.FileSharing.SMB2Model.Adapter.Encryption.EncryptionConfig>(this.Manager, this.v2, this.c1, "v2 == c1");
            this.Manager.Assert(TestManagerHelpers.Equality(((object)(System.Convert.ToInt32(this.v2.Value.IsGlobalRejectUnencryptedAccessEnabled))), ((object)(System.Convert.ToInt32(this.c.Value.IsGlobalRejectUnencryptedAccessEnabled)))), "Fail to check the assumption : v2.IsGlobalRejectUnencryptedAccessEnabled == c.IsG" +
